        return out
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    density = len(pts) / ((r1 - r0 + 1) * (c1 - c0 + 1))

    if density >= 0.2:
        # Dense figure: repair one-cell breaks in straight runs.
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == bg and (
                    (c > 0 and c + 1 < w and grid[r][c - 1] != bg and grid[r][c + 1] != bg)
                    or (r > 0 and r + 1 < h and grid[r - 1][c] != bg and grid[r + 1][c] != bg)
                ):
                    out[r][c] = 2
    else:
        # Sparse point pattern: draw its bounding frame and join points on shared rows.
        def paint(r, c):
